import{_ as o,o as t,c,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — G1 Authentication (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g1-auth/plan.md","filePath":"mobile/features/g1-auth/plan.md"}'),i={name:"mobile/features/g1-auth/plan.md"};function a(l,e,r,d,h,s){return t(),c("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-—-g1-authentication-mobile" tabindex="-1">Plan — G1 Authentication (Mobile) <a class="header-anchor" href="#plan-—-g1-authentication-mobile" aria-label="Permalink to &quot;Plan — G1 Authentication (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/state đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>Infra chung trước</strong> — không màn hình nào chạy được nếu thiếu: <ul><li>Axios instance + interceptor auto-refresh 401 (gọi <code>POST /auth/refresh</code>, retry request gốc).</li><li><code>expo-secure-store</code> wrapper: <code>getTokens()</code>, <code>setTokens()</code>, <code>clearTokens()</code>.</li><li><code>useAuthStore</code> (Zustand) theo state ở spec mục 5.</li><li>Bảng message lỗi tiếng Việt tập trung (map <code>ErrorCode</code> → string hiển thị).</li></ul></li><li><strong>Login + Register + OTP</strong> (block lõi, các màn khác phụ thuộc): <ul><li><code>useLoginMutation</code>, <code>useRegisterMutation</code>, <code>useVerifyOtpMutation</code>, <code>useResendOtpMutation</code>.</li><li>Screen: <code>Login</code>, <code>Register</code>, <code>VerifyOtp</code> (dùng chung).</li></ul></li><li><strong>Forgot/Reset Password</strong>: <ul><li><code>useForgotPasswordMutation</code>, <code>useResetPasswordMutation</code>.</li><li>Screen: <code>ForgotPassword</code>, <code>ResetPassword</code> — chỉ nhánh deep link (xem spec mục 8 câu 4, đã xác nhận backend không gửi OTP cho flow này).</li><li>Deep link scheme đăng ký trong <code>app.json</code>/<code>app.config.ts</code> (chốt <code>brandhub</code>, dùng chung với OAuth callback).</li></ul></li><li><strong>Google OAuth</strong>: <ul><li>Thêm query <code>?client=mobile</code> khi gọi <code>startUrl</code> (backend đã hỗ trợ, xem spec mục 8 câu 1).</li><li><code>WebBrowser.openAuthSessionAsync</code> + <code>expo-auth-session</code> <code>makeRedirectUri</code>.</li><li>Parse <code>result.url</code> → <code>token</code>/<code>error</code> → gọi tiếp <code>GET /api/v1/users/me</code> lấy profile đầy đủ.</li></ul></li><li><strong>2FA Verify</strong>: <ul><li><code>useVerifyTwoFactorMutation</code>.</li><li>Screen <code>TwoFactorVerify</code>, nhận <code>twoFactorToken</code> qua navigation param (không SecureStore).</li></ul></li><li><strong>Logout</strong>: <ul><li><code>useLogoutMutation</code> — <strong>phải gửi <code>refreshToken</code> trong body</strong> (<code>{ refreshToken }</code>), backend đã sửa để nhận field này (spec mục 8 câu 3b). Luôn <code>clearAuth()</code> ở <code>onSettled</code> dù API lỗi.</li><li>Lưu &quot;last used platform&quot; (FR 3.2.8) vào AsyncStorage, giữ nguyên qua <code>clearAuth()</code>.</li></ul></li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>Deep link scheme</strong>: <code>brandhub://oauth-callback</code> — đã xác nhận với backend (<code>app.mobile-redirect-uri</code> config), dùng chung cho cả OAuth callback.</li><li><strong>Forgot/Reset Password</strong>: chỉ 1 nhánh (deep link token), không code nhánh OTP — bỏ hẳn khỏi UI để tránh màn hình thừa.</li><li><strong>Resend OTP cooldown</strong>: 60 giây cố định, client tự đếm ngược, không đọc field nào từ response.</li><li><strong>Profile đầy đủ</strong>: gọi <code>GET /api/v1/users/me</code> (không phải <code>/api/v1/auth/me</code>) sau khi có token — domain Profile ngoài scope G1 nhưng G1 vẫn phải gọi 1 lần ngay sau login/OAuth để có <code>fullName</code>/<code>avatarUrl</code>/<code>role</code> cho Zustand store.</li></ul><h2 id="viec-backend-đa-lam-xong-khong-can-hoi-lai" tabindex="-1">Việc backend đã làm xong (không cần hỏi lại) <a class="header-anchor" href="#viec-backend-đa-lam-xong-khong-can-hoi-lai" aria-label="Permalink to &quot;Việc backend đã làm xong (không cần hỏi lại)&quot;">​</a></h2><ul><li><code>POST /auth/logout</code> nhận <code>refreshToken</code> qua body (fallback khi không có cookie).</li><li><code>GET /auth/oauth/google?client=mobile</code> → callback redirect về <code>app.mobile-redirect-uri</code> nếu set, không thì fallback web — mobile cần đảm bảo giá trị env <code>APP_MOBILE_REDIRECT_URI</code> đã set đúng ở môi trường test trước khi integration test OAuth thật.</li></ul><h2 id="rui-ro-con-mo-xem-chi-tiet-spec-muc-8" tabindex="-1">Rủi ro còn mở (xem chi tiết spec mục 8) <a class="header-anchor" href="#rui-ro-con-mo-xem-chi-tiet-spec-muc-8" aria-label="Permalink to &quot;Rủi ro còn mở (xem chi tiết spec mục 8)&quot;">​</a></h2><ul><li>Google OAuth nhánh lỗi (<code>businessFailure</code>, <code>loginFailure</code>) chưa phân biệt được mobile/web vì <code>state</code> đã bị xoá trước khi exception ném ra — mọi lỗi OAuth đều redirect về web URL, không về app. Mobile cần coi &quot;không thấy redirect quay lại app trong X giây&quot; là 1 dạng lỗi, không chỉ trông chờ <code>error=...</code> query param.</li><li>Universal Links/App Links (https://) cho reset-password chưa quyết định — một số email client Android/iOS có thể chặn custom scheme <code>brandhub://</code>, cần test tay trên thiết bị thật trước khi release.</li></ul>',10)])])}const m=o(i,[["render",a]]);export{g as __pageData,m as default};
